// Hall datchigi — aylanish tezligini (RPM) oʻlchash
const int HALL = 2;              // Unoʻda uzilish pini
volatile unsigned int impuls = 0;
unsigned long oxirgi = 0;

void sanash() { impuls++; }      // uzilishda chaqiriladi — juda qisqa boʻlishi kerak

void setup() {
  pinMode(HALL, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(HALL), sanash, FALLING);
  Serial.begin(9600);
}

void loop() {
  if (millis() - oxirgi >= 1000) {          // har sekundda hisoblaymiz
    oxirgi = millis();

    noInterrupts();
    unsigned int n = impuls;
    impuls = 0;
    interrupts();

    unsigned int rpm = n * 60;              // gʻildirakda 1 ta magnit boʻlsa

    Serial.print("Sekundiga aylanish: "); Serial.print(n);
    Serial.print("   RPM: ");              Serial.println(rpm);
  }
}

