const int LED = 9;            // PWM pin (~ belgisi bor)

void setup() {
  pinMode(LED, OUTPUT);
}

void loop() {
  // 1) oddiy miltillash
  digitalWrite(LED, HIGH);  delay(500);
  digitalWrite(LED, LOW);   delay(500);

  // 2) asta yorishish (PWM)
